contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr, address logAddr2) public {
        // Fresh contract: MinSum must start at 0.
        require(c.MinSum() == 0);

        // First SetLogFile on an uninitialized contract must succeed.
        bool reverted1;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        // Repeating SetLogFile before initialization is still allowed.
        bool reverted2;
        c.SetLogFile(logAddr2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        assert(!reverted1 && !reverted2 && c.MinSum() == 0);
    }

    receive() external payable {}
}

